/* ===================== BÀI 31 · BIOS và giả định nền tảng PC ===================== */
/* Bài 31 · BIOS và giả định nền tảng PC (AMTS-EMB-002-M08-L03, X86-031) — sinh bởi tools/author/mpu8086/l31.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8086 và bài tập chấm tự động (đề, code mẫu, test). Lời giải không nằm ở đây. */
const P31=[{"label": "Ví dụ: in chuỗi bằng BIOS (INT 10h, 0Eh)", "code": "; Ví dụ 1: in chuỗi bằng BIOS (INT 10h, hàm 0Eh)\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nmsg     DB      'BIOS in', 0            ; chuỗi kết thúc bằng byte 0\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     SI, OFFSET msg\n        MOV     AH, 0EH                 ; in ký tự kiểu máy chữ\n        MOV     BH, 0                   ; trang màn hình 0\nLAP:\n        MOV     AL, [SI]\n        CMP     AL, 0\n        JE      XONG\n        INT     10H                     ; in AL, con trỏ dời sang phải\n        INC     SI\n        JMP     LAP\nXONG:\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "In chuỗi kết thúc bằng byte 0 (không dùng '$') bằng INT 10h hàm 0Eh: mỗi ký tự một lần gọi, con trỏ tự dời sang phải. AH = 0Eh đặt một lần trước vòng được vì vòng này không gọi dịch vụ nào trả về AH. Mỗi ký tự tốn 13 + 4 + 4 + 51 + 2 + 15 = 89 chu kỳ phía chương trình. Đoán trước: lần CMP AL, 0 thứ mấy thì JE nhảy? Đáp án lần thứ 8 (sau 7 ký tự)."}, {"label": "Ví dụ: đặt con trỏ, in, đọc con trỏ", "code": "; Ví dụ 2: đặt con trỏ (02h), in, rồi đọc con trỏ (03h)\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nhang    DB      ?\ncot     DB      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AH, 02H                 ; đặt con trỏ\n        MOV     BH, 0\n        MOV     DH, 2                   ; hàng 2\n        MOV     DL, 5                   ; cột 5\n        INT     10H\n        MOV     AX, 0E58H               ; AH = 0Eh, AL = 'X'\n        INT     10H\n        MOV     AH, 03H                 ; đọc con trỏ → DH, DL\n        MOV     BH, 0\n        INT     10H\n        MOV     hang, DH\n        MOV     cot, DL\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Hàm 02h đặt con trỏ ở hàng 2, cột 5; MOV AX, 0E58h đặt cùng lúc AH = 0Eh và AL = 'X'; hàm 0Eh in X ở ô B800:014Ah (2 × 160 + 5 × 2) và dời con trỏ sang cột 6; hàm 03h trả DH = 2, DL = 6. Chọn vùng B800h ở phần Bộ nhớ để thấy byte 58 07. Đoán trước: sau hàm 03h, DL bằng bao nhiêu? Đáp án 06h."}, {"label": "Bẫy: hàm 09h của BIOS không dời con trỏ", "code": "; Ví dụ 3: BẪY - hàm 09h không dời con trỏ\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nmsg     DB      'ABC'\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     SI, OFFSET msg\n        MOV     CX, 3\nLAP:\n        PUSH    CX\n        MOV     AL, [SI]\n        MOV     AH, 09H                 ; ghi ký tự + thuộc tính tại con trỏ\n        MOV     BH, 0\n        MOV     BL, 1EH                 ; chữ vàng nền xanh\n        MOV     CX, 1                   ; số lần lặp ký tự\n        INT     10H                     ; con trỏ KHÔNG dời\n        INC     SI\n        POP     CX\n        LOOP    LAP\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Bẫy: hàm 09h ghi ký tự và thuộc tính tại con trỏ nhưng không dời con trỏ. Ba lần gọi ghi A, B, C cùng vào ô (0,0); màn hình chỉ còn C (thuộc tính 1Eh: 43 1E ở B800:0000). Luồng chữ in dùng để chấm cũng chỉ còn C (sửa sau tích hợp: trước đây trình mô phỏng ghi ABC, khác màn hình). Sửa: dùng hàm 0Eh, hoặc đặt con trỏ bằng hàm 02h sau mỗi ký tự. PUSH CX/POP CX giữ bộ đếm vòng vì hàm 09h dùng CX. Đoán trước: sau lần INT 10h thứ hai, con trỏ ở cột nào? Đáp án cột 0."}, {"label": "Ví dụ: ghi thẳng B800h kèm thuộc tính", "code": "; Ví dụ 4: ghi thẳng bộ nhớ màn hình với thuộc tính\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        MOV     AX, 0B800H\n        MOV     ES, AX\n        MOV     DI, 160 * 1 + 2 * 3     ; hàng 1, cột 3\n        MOV     AX, 1E48H               ; AH = thuộc tính 1Eh, AL = 'H'\n        MOV     ES:[DI], AX             ; byte thấp (ký tự) ở địa chỉ thấp\n        MOV     AX, 1E69H               ; 'i'\n        MOV     ES:[DI+2], AX\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Ghi thẳng hai ô ở hàng 1, cột 3 và 4: DI = 160 × 1 + 2 × 3 = 166 = 00A6h (trình dịch tính biểu thức). MOV AX, 1E48h rồi MOV ES:[DI], AX ghi 48 1E: ký tự H, thuộc tính 1Eh (vàng trên xanh lam, xem Hình 31.2). Không qua DOS hay BIOS nên luồng chữ in rỗng; xem Màn hình DOS (hàng 1) và vùng B800h. MOV ES:[DI], AX tốn 9 + EA 5 + 2 = 16 chu kỳ. Đoán trước: byte ở B80A7h là gì? Đáp án 1Eh."}, {"label": "Lỗi: ghi word ký tự/thuộc tính ngược", "code": "; Ví dụ 5: LỖI - ghi word ký tự/thuộc tính ngược thứ tự\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        MOV     AX, 0B800H\n        MOV     ES, AX\n        MOV     AX, 4107H               ; ý định: 'A' (41h), thuộc tính 07h\n        MOV     ES:[0], AX              ; nhưng byte 07h vào ô ký tự\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Lỗi cố ý: muốn A (41h) thuộc tính 07h nhưng viết MOV AX, 4107h. Word ghi byte thấp 07h vào ô ký tự và 41h vào ô thuộc tính: màn hình hiện ký tự số 7 của bảng CP437 (dấu chấm tròn •), nền đỏ chữ xanh lam trên card màu. Sửa: MOV AX, 0741h (AH = thuộc tính, AL = ký tự). Đoán trước: byte ở B8000h là gì? Đáp án 07h."}, {"label": "Ví dụ: đọc phím bằng INT 16h", "code": "; Ví dụ 6: đọc phím bằng BIOS (INT 16h, hàm 00h)\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nascii   DB      ?\nquet    DB      ?                       ; mã quét của phím\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AH, 00H                 ; chờ một phím\n        INT     16H                     ; AL = ASCII, AH = mã quét\n        MOV     ascii, AL\n        MOV     quet, AH\n        MOV     AH, 0EH                 ; in lại phím bằng BIOS\n        INT     10H\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "k", "note": "INT 16h hàm 00h chờ một phím, trả AL = mã ASCII ('k' = 6Bh) và AH = mã quét. Trình mô phỏng chưa có mã quét nên AH = 0; trên PC thật với bàn phím Mỹ, phím K có mã quét 25h (CẦN XÁC MINH bảng mã quét). Hàm 0Eh in lại phím; khác hàm 08h của DOS ở chỗ không qua DOS, không kiểm Ctrl-C, không chuyển hướng được. Đoán trước: sau INT 16h, AL bằng bao nhiêu? Đáp án 6Bh."}, {"label": "Lỗi: INT 16h đổi AH, quên đặt 0Eh", "code": "; Ví dụ 7: LỖI - INT 16h đổi AH, quên đặt lại 0Eh\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        MOV     CX, 2\nLAP:\n        MOV     AH, 00H\n        INT     16H                     ; AH = mã quét (trình mô phỏng: 0)\n        INT     10H                     ; tưởng là hàm 0Eh\n        LOOP    LAP\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "ab", "note": "Lỗi cố ý: MOV AH, 00h / INT 16h ghi đè AH bằng mã quét (0 trên trình mô phỏng), nên INT 10h kế tiếp là hàm 00h đặt chế độ màn hình theo AL (61h, 62h): màn hình bị xóa, không có chữ nào. Trên PC thật AH là mã quét (1Eh với phím a), INT 10h gọi một hàm khác, cũng sai. Sửa: MOV AH, 0Eh ngay trước INT 10h. Đoán trước: ngay trước INT 10h đầu tiên, AH bằng bao nhiêu trên trình mô phỏng? Đáp án 00h."}, {"label": "Ví dụ: vùng dữ liệu BIOS 0040h", "code": "; Ví dụ 8: đọc vùng dữ liệu BIOS ở đoạn 0040h\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nchedo   DB      ?                       ; chế độ màn hình\ncot     DB      ?\nhang    DB      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AX, 0E4FH               ; in 'O' rồi 'K' bằng BIOS\n        INT     10H\n        MOV     AL, 'K'\n        INT     10H\n        MOV     AX, 0040H\n        MOV     ES, AX                  ; ES = vùng dữ liệu BIOS\n        MOV     AL, ES:[49H]            ; 0040:0049 chế độ màn hình\n        MOV     chedo, AL\n        MOV     AX, ES:[50H]            ; 0040:0050 cột, 0051 hàng\n        MOV     cot, AL\n        MOV     hang, AH\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "In OK bằng hàm 0Eh (AL đổi thành 'K', AH vẫn 0Eh do trình mô phỏng giữ AH), rồi đọc thẳng vùng dữ liệu BIOS: 0040:0049 = 03 (chế độ văn bản 80 × 25 màu), word 0040:0050 = 0002h nên cột 2 (byte thấp), hàng 0 (byte cao). MOV AL, ES:[49h] dạng A0 tốn 10 + 2 chu kỳ. Đoán trước: sau MOV AX, ES:[50h], AX bằng bao nhiêu? Đáp án 0002h."}];
const sim31=makeX86Sim(document.getElementById("x86-l31"),{id:"s31",presets:P31,file:"BAI31.ASM"});
makeX86Ex(document.getElementById("ex-l31"),sim31,[{"t": "Sửa chương trình gõ phím bằng BIOS", "d": "Đọc phím bằng INT 16h hàm 00h tới khi gặp dấu chấm, in mỗi phím bằng INT 10h hàm 0Eh; phím Enter (0Dh) in thành CR rồi LF (0Ah). Code mẫu chỉ đặt AH = 0Eh một lần trước vòng lặp nên không in gì đúng. Sửa để chương trình in đúng. Kết thúc bằng INT 21h hàm 4Ch.", "start": "; Bài tập 1: gõ phím và in bằng BIOS (có lỗi cần sửa)\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        MOV     AH, 0EH                 ; LỖI: chỉ đặt một lần\nDOC:\n        MOV     AH, 00H\n        INT     16H                     ; AL = phím, AH = mã quét\n        CMP     AL, '.'\n        JE      HET\n        CMP     AL, 13                  ; Enter?\n        JNE     IN1\n        INT     10H                     ; in CR\n        MOV     AL, 10                  ; rồi LF\nIN1:\n        INT     10H\n        JMP     DOC\nHET:\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"in": "abc.", "out": "abc"}, {"in": "8086 asm.", "out": "8086 asm"}, {"in": ".", "out": ""}, {"in": "Xin\nchao.", "out": "Xin\r\nchao"}, {"in": "a\n\nb.", "out": "a\r\n\r\nb"}, {"in": "Hi!?.", "out": "Hi!?"}]}, {"t": "Con trỏ ở đâu sau khi in?", "d": "Chương trình in các phím gõ vào (tới dấu chấm) bằng INT 10h hàm 0Eh, Enter thành CR LF, rồi gọi INT 10h hàm 03h (BH = 0) để hỏi BIOS vị trí con trỏ và ghi vào hai biến byte hang, cot. Code mẫu ghi nhầm. Sửa lại. Màn hình rộng 80 cột: in tới cột 79 thì con trỏ tự xuống đầu hàng sau. Kết thúc bằng INT 21h hàm 4Ch.", "start": "; Bài tập 2: con trỏ ở đâu sau khi in? (có lỗi cần sửa)\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nhang    DB      ?\ncot     DB      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\nDOC:\n        MOV     AH, 00H\n        INT     16H\n        CMP     AL, '.'\n        JE      HET\n        CMP     AL, 13\n        JNE     IN1\n        MOV     AH, 0EH\n        INT     10H\n        MOV     AL, 10\nIN1:\n        MOV     AH, 0EH\n        INT     10H\n        JMP     DOC\nHET:\n        MOV     AH, 03H                 ; đọc con trỏ trang 0\n        MOV     BH, 0\n        INT     10H\n        MOV     hang, DL                ; LỖI\n        MOV     cot, DH\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"in": "abc.", "out": "abc", "mem": [{"at": "hang", "bytes": [0]}, {"at": "cot", "bytes": [3]}]}, {"in": "Xin\nchao.", "out": "Xin\r\nchao", "mem": [{"at": "hang", "bytes": [1]}, {"at": "cot", "bytes": [4]}]}, {"in": "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa.", "out": "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa", "mem": [{"at": "hang", "bytes": [1]}, {"at": "cot", "bytes": [5]}]}, {"in": "\n\n\n.", "out": "\r\n\r\n\r\n", "mem": [{"at": "hang", "bytes": [3]}, {"at": "cot", "bytes": [0]}]}, {"in": "Hello\nAMTS 8086.", "out": "Hello\r\nAMTS 8086", "mem": [{"at": "hang", "bytes": [1]}, {"at": "cot", "bytes": [9]}]}, {"in": ".", "out": "", "mem": [{"at": "hang", "bytes": [0]}, {"at": "cot", "bytes": [0]}]}]}, {"t": "Đếm ô 'X' trên màn hình thật nhanh", "d": "Chương trình đọc phím bằng INT 21h hàm 08h tới dấu chấm và in từng phím bằng hàm 02h (đã viết sẵn; dữ liệu chấm không quá 80 phím, không có Enter, nên mọi chữ nằm ở hàng 0). Sau đó phải đếm số ô ở hàng 0 của màn hình (80 ô đầu tiên của đoạn B800h) chứa chữ X hoa và ghi vào biến dem. Phải đọc chính bộ nhớ màn hình, không đếm lúc nhập. Giả định: mọi ô có thuộc tính 07h (đúng trên trình mô phỏng; trên PC thật tùy màn hình trước đó). Code mẫu đếm bằng vòng lặp từng ô, đúng nhưng chậm. Viết lại phần đếm để chương trình chạy không quá 13000 chu kỳ ở test dài nhất và mã không quá 60 byte.", "start": "; Bài tập 3: đếm ô 'X' ở hàng 0 - đúng nhưng chậm\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\ndem     DB      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\nDOC:\n        MOV     AH, 08H                 ; đọc phím, in qua DOS\n        INT     21H\n        CMP     AL, '.'\n        JE      DEMX\n        MOV     DL, AL\n        MOV     AH, 02H\n        INT     21H\n        JMP     DOC\nDEMX:\n        MOV     AX, 0B800H\n        MOV     ES, AX\n        MOV     DI, 0\n        MOV     CX, 80                  ; 80 ô của hàng 0\n        MOV     BL, 0\nDEM1:\n        CMP     BYTE PTR ES:[DI], 'X'\n        JNE     KHAC\n        INC     BL\nKHAC:\n        ADD     DI, 2                   ; ô kế tiếp: 2 byte\n        LOOP    DEM1\n        MOV     dem, BL\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"in": "XXX.", "out": "XXX", "mem": [{"at": "dem", "bytes": [3]}]}, {"in": "AXBXC.", "out": "AXBXC", "mem": [{"at": "dem", "bytes": [2]}]}, {"in": ".", "out": "", "mem": [{"at": "dem", "bytes": [0]}]}, {"in": "xX X.", "out": "xX X", "mem": [{"at": "dem", "bytes": [2]}]}, {"in": "xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxX.", "out": "xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxX", "mem": [{"at": "dem", "bytes": [1]}]}, {"in": "X------------------------------------------------------------------------------X.", "out": "X------------------------------------------------------------------------------X", "mem": [{"at": "dem", "bytes": [2]}]}], "perf": {"cycles": 13000, "bytes": 60}}]);

makeQuiz("quiz31","score31",[{"q": "Ở chế độ văn bản 3 (80 × 25), ô hàng 10, cột 40 nằm ở địa chỉ nào?", "o": ["B800:0690h (byte ký tự), B800:0691h (thuộc tính)", "B800:0428h", "B800:0320h (byte ký tự), B800:0321h (thuộc tính)", "B000:0690h"], "a": 0, "e": "Độ lệch = 10 × 160 + 40 × 2 = 1600 + 80 = 1680 = 0690h. B000h là đoạn của card đơn sắc, không phải chế độ 3."}, {"q": "ES = B800h, DI = 0. Sau <code>MOV AX, 1E41h<\/code> / <code>MOV ES:[DI], AX<\/code>, ô đầu màn hình hiện gì trên card màu?", "o": ["Chữ A vàng trên nền xanh lam", "Ký tự mã 1Eh trên nền đỏ", "Chữ A xám trên nền đen", "Không đổi, vì phải ghi từng byte riêng"], "a": 0, "e": "Word ghi byte thấp 41h ('A') vào ô ký tự, byte cao 1Eh vào ô thuộc tính: nền 001 (xanh lam), chữ sáng + 110 (nâu sáng = vàng)."}, {"q": "Vòng lặp đặt <code>MOV AH, 0Eh<\/code> một lần ở đầu, trong vòng gọi <code>MOV AH, 0<\/code> / <code>INT 16h<\/code> rồi <code>INT 10h<\/code>. Lỗi nằm ở đâu?", "o": ["INT 16h hàm 00h không chờ phím nên AL rỗng", "INT 16h trả mã quét trong AH, nên INT 10h không còn là hàm 0Eh", "INT 10h hàm 0Eh cần ký tự trong DL chứ không phải AL", "Không lỗi: BIOS giữ nguyên AH qua mọi lần gọi"], "a": 1, "e": "INT 16h hàm 00h trả AX: AL = ASCII, AH = mã quét. Phải đặt lại AH = 0Eh ngay trước mỗi INT 10h (Ví dụ 7)."}, {"q": "Người dùng chạy <code>BAI31 &gt; KQ.TXT<\/code>. Chữ in bằng cách nào sẽ vào tệp KQ.TXT?", "o": ["Chữ in bằng INT 10h hàm 0Eh", "Chỉ chữ in bằng INT 21h hàm 02h, 09h", "Chữ ghi thẳng vào B800h", "Cả ba cách, vì DOS chặn mọi lần ghi màn hình"], "a": 1, "e": "Chuyển hướng là việc của DOS với thiết bị ra chuẩn. BIOS và ghi thẳng bộ nhớ màn hình đi vòng qua DOS nên chữ vẫn hiện trên màn hình và không vào tệp."}, {"q": "Chương trình ghi thẳng vào B800h chạy trên một PC chỉ có card đơn sắc MDA (chế độ 7). Cách làm đúng để chương trình chạy được trên cả hai loại card là gì?", "o": ["Luôn dùng B800h vì mọi card đều có vùng nhớ ở đó", "Gọi INT 10h hàm 00h đặt chế độ 3 trên card MDA", "Đọc chế độ màn hình (INT 10h hàm 0Fh hoặc byte 0040:0049); chế độ 7 thì dùng đoạn B000h", "Dùng INT 16h để hỏi loại card màn hình"], "a": 2, "e": "Card MDA có bộ nhớ văn bản ở B000h và không có chế độ 3. Chương trình phải đọc chế độ hiện tại rồi chọn đoạn; INT 16h là dịch vụ bàn phím."}]);

